package harkenscythe.gen;

import hexxit.worldgen152.core.populate.OldLoot;
import hexxit.worldgen152.core.populate.OldStack;

/**
 * mod_HarkenScythe.setCustomDungeonLoots: a Necronomicon page (weight 5) in the chests of villages, dungeons,
 * mineshafts, temples and strongholds. The bonus chest is not generated by worldgen152; its page comes from the global
 * loot modifier {@code harkenscythe_core:necronomicon_page_bonus_chest}. No game classes, so tools/expect.sh can use it.
 */
public final class HSWorldGen {
    /** "Book- Necronomicon Page" of the pack's HarkenScythe_Core.cfg (5591), plus 256 like every item id of 1.5.2. */
    public static final int NECRONOMICON_PAGE = 5591 + 256;

    private HSWorldGen() {
    }

    public static void register() {
        OldLoot.Category[] categories = {OldLoot.VILLAGE_BLACKSMITH, OldLoot.DUNGEON_CHEST, OldLoot.MINESHAFT_CORRIDOR,
                OldLoot.PYRAMID_DESERT_CHEST, OldLoot.PYRAMID_JUNGLE_CHEST, OldLoot.STRONGHOLD_CORRIDOR, OldLoot.STRONGHOLD_CROSSING,
                OldLoot.STRONGHOLD_LIBRARY};
        for (OldLoot.Category category : categories) {
            category.add("HarkenScythe_Core", new OldStack(NECRONOMICON_PAGE, 0, 1), 1, 1, 5);
        }
    }
}
